CREATE TABLE IF NOT EXISTS app_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_subject text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), lease_token uuid, lease_expires_at timestamptz);
CREATE TABLE IF NOT EXISTS sample_catalog(id text PRIMARY KEY, family text NOT NULL, manifest jsonb NOT NULL, license_status text NOT NULL, enabled integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS datasets(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_users(id), name text NOT NULL, status text NOT NULL CHECK(status IN ('created','uploaded','ready','failed','deleting')), metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS datasets_owner_date ON datasets(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS dataset_columns(id text NOT NULL, dataset_id uuid NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, ordinal integer NOT NULL, profile jsonb NOT NULL, PRIMARY KEY(dataset_id,id), UNIQUE(dataset_id,ordinal));
CREATE TABLE IF NOT EXISTS dataset_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, storage_key text NOT NULL,kind text NOT NULL CHECK(kind IN ('raw','normalized')),sha256 text,byte_size integer NOT NULL,is_shared_seed integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS analyses(id uuid PRIMARY KEY, dataset_id uuid NOT NULL REFERENCES datasets(id) ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES app_users(id), status text NOT NULL CHECK(status IN ('running','completed','failed')), metadata jsonb NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,cache_key text NOT NULL, lease_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS analyses_dataset_date ON analyses(dataset_id,created_at DESC);
CREATE INDEX IF NOT EXISTS analyses_status_lease ON analyses(status,lease_expires_at);
CREATE INDEX IF NOT EXISTS analyses_cache ON analyses(owner_id,cache_key,status);
CREATE TABLE IF NOT EXISTS analysis_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),analysis_id uuid NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,kind text NOT NULL,result_key text NOT NULL,payload jsonb,storage_key text,CHECK((payload IS NOT NULL) <> (storage_key IS NOT NULL)),UNIQUE(analysis_id,kind,result_key));
CREATE TABLE IF NOT EXISTS exports(id uuid PRIMARY KEY,analysis_id uuid NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,format text NOT NULL CHECK(format IN ('json','csv')),storage_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_daily(owner_id uuid NOT NULL REFERENCES app_users(id),usage_date text NOT NULL,analysis_count integer NOT NULL DEFAULT 0 CHECK(analysis_count>=0),PRIMARY KEY(owner_id,usage_date));
